import React, { useContext } from 'react';
import { useHistory } from 'react-router-dom';
import { CartContext } from '../../context/CartContext';
import Header from '../../components/client/Header';
import Footer from '../../components/client/Footer';
import '../../styles/home.css';

function CartSummary() {
    const { cartItems, setCartItems } = useContext(CartContext);
    const history = useHistory();

    const updateQuantity = (idItem, newQuantity) => {
        if (newQuantity <= 0) {
            removeItem(idItem);
            return;
        }
        setCartItems(cartItems.map(item => 
            item.idItem === idItem ? { ...item, quantity: newQuantity } : item
        ));
    };

    const removeItem = (idItem) => {
        setCartItems(cartItems.filter(item => item.idItem !== idItem));
    };

    const total = cartItems.reduce((acc, item) => acc + item.price * item.quantity, 0);

    return (
        <div className="home">
            <Header />
            <div className="container" style={{ display: 'block', maxWidth: '800px', margin: '40px auto', minHeight: '60vh' }}>
                <h1 style={{ marginBottom: '20px' }}>Récapitulatif de votre panier</h1>
                
                {cartItems.length === 0 ? (
                    <p>Votre panier est vide.</p>
                ) : (
                    <div>
                        {cartItems.map((item, index) => (
                            <div key={index} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '15px', borderBottom: '1px solid #ccc' }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                                    <img src={item.image} alt={item.name} style={{ width: '80px', height: '80px', objectFit: 'cover', borderRadius: '8px' }} />
                                    <div>
                                        <h3>{item.name}</h3>
                                        <p>{item.price} €</p>
                                    </div>
                                </div>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                                    <div>
                                        <label style={{ marginRight: '10px' }}>Quantité: </label>
                                        <input 
                                            type="number" 
                                            min="0" 
                                            value={item.quantity} 
                                            onChange={(e) => updateQuantity(item.idItem, parseInt(e.target.value) || 0)}
                                            style={{ width: '60px', padding: '5px' }}
                                        />
                                    </div>
                                    <button 
                                        onClick={() => removeItem(item.idItem)}
                                        style={{ backgroundColor: '#ff4d4f', color: 'white', border: 'none', padding: '8px 12px', borderRadius: '4px', cursor: 'pointer' }}
                                    >
                                        Supprimer
                                    </button>
                                </div>
                            </div>
                        ))}
                        
                        <div style={{ marginTop: '30px', textAlign: 'right' }}>
                            <h2>Total : {total.toFixed(2)} €</h2>
                            <button 
                                onClick={() => history.push('/checkout')}
                                style={{ backgroundColor: '#1890ff', color: 'white', border: 'none', padding: '12px 24px', fontSize: '18px', borderRadius: '4px', cursor: 'pointer', marginTop: '15px' }}
                            >
                                Payer
                            </button>
                        </div>
                    </div>
                )}
            </div>
            <Footer />
        </div>
    );
}

export default CartSummary;
